<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AppLayout from'../../../Layouts/AppLayout.vue';const p=defineProps({batches:Object,courses:Array,limits:Object});const form=useForm({file:null,course_mode:'selected',course_id:'',existing_policy:'ENROLL_EXISTING_ONLY'});</script>
<template><AppLayout><Head title="ورود گروهی هنرجویان"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><h1 class="text-xl font-bold">مرحله ۱ — بارگذاری</h1><p class="mt-2 text-sm text-slate-500">CSV یا XLSX، حداکثر {{limits.max_rows}} ردیف و {{limits.max_file_kb/1024}} مگابایت. ستون‌های first_name، last_name و mobile الزامی‌اند.</p><Link href="/admin/student-imports/template" class="mt-3 inline-block text-teal-700">دریافت فایل نمونه</Link><form class="mt-5 grid gap-4 sm:grid-cols-2" @submit.prevent="form.post('/admin/student-imports',{forceFormData:true})"><input type="file" accept=".csv,.xlsx" @change="form.file=$event.target.files[0]"><select v-model="form.course_mode"><option value="selected">یک دوره برای همه</option><option value="slug">ستون course_slug</option></select><select v-if="form.course_mode==='selected'" v-model="form.course_id"><option value="">انتخاب دوره</option><option v-for="c in courses" :key="c.id" :value="c.id">{{c.title}}</option></select><select v-model="form.existing_policy"><option value="ENROLL_EXISTING_ONLY">ثبت‌نام هنرجوی موجود</option><option value="SKIP_EXISTING">ردکردن هنرجوی موجود</option></select><p class="text-red-600 sm:col-span-2">{{form.errors.file||form.errors.course_id}}</p><button class="w-fit rounded-xl bg-teal-700 px-5 py-2 text-white">بررسی و پیش‌نمایش</button></form></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">تاریخچه ورودها</h2><Link v-for="b in batches.data" :key="b.id" :href="`/admin/student-imports/${b.id}`" class="mt-3 block rounded-xl border p-3"><strong>{{b.original_filename}}</strong><p class="text-sm">{{b.status}} · {{b.total_rows}} ردیف · {{b.created_users}} کاربر · {{b.created_enrollments}} ثبت‌نام</p></Link></section></div></AppLayout></template>
